    disposition: "AUDIT",
    tokenId,
    observedTokenContentHash,
    bundleCid: input.bundleCid,
    senderTransportPubkey: input.senderTransportPubkey,
    auditStatus: kind === "not-our-state" ? "audit-not-our-state" : "audit-off-record-spend",
    reason: kind
