      id: crypto.randomUUID(),
      coinId: tokenInfo.coinId,
      symbol: tokenInfo.symbol,
      name: tokenInfo.name,
      decimals: tokenInfo.decimals,
      iconUrl: tokenInfo.iconUrl,
      amount: tokenInfo.amount,
      status: "submitted",
      // NOSTR-FIRST: unconfirmed until proof
      createdAt: Date.now(),
      updatedAt: Date.now(),
      sdkData
