      const commitment = await TransferCommitment4.fromJSON(commitmentInput);
      const requestIdBytes = commitment.requestId;
      const requestIdHex = requestIdBytes instanceof Uint8Array ? Array.from(requestIdBytes).map((b) => b.toString(16).padStart(2, "0")).join("") : typeof requestIdBytes.toJSON === "function" ? requestIdBytes.toJSON() : String(requestIdBytes);
