        const receivedTokenId = extractTokenIdFromSdkData(uiToken.sdkData);
        const senderInfo = await this.resolveSenderInfo(senderPubkey);
        await this.addToHistory({
          type: "RECEIVED",
          amount: bundle.amount,
          coinId: info.coinId,
          symbol: info.symbol,
          timestamp: Date.now(),
          senderPubkey,
          ...senderInfo,
          memo,
          tokenId: receivedTokenId || uiToken.id
        });
